package com.tmevolut.ecommerce.api.controller;
import com.tmevolut.ecommerce.api.dto.*; import com.tmevolut.ecommerce.api.service.ClienteService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@Tag(name="Clientes") @RestController @RequestMapping("/api/v1/clientes")
public class ClienteController { private final ClienteService service; public ClienteController(ClienteService service){this.service=service;}
@GetMapping public Page<ClienteResponse> listar(Pageable pageable){return service.listar(pageable);} @GetMapping("/{id}") public ClienteResponse buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping public ResponseEntity<ClienteResponse> criar(@Valid @RequestBody ClienteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.criar(r));} @PutMapping("/{id}") public ClienteResponse atualizar(@PathVariable Long id,@Valid @RequestBody ClienteRequest r){return service.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> remover(@PathVariable Long id){service.remover(id);return ResponseEntity.noContent().build();}}
